import { Test, TestingModule } from '@nestjs/testing';
import { InfluxModule } from '../influx/influx.module';
import { CustomerService } from './customer.service';
import { SchedulerModule } from '../scheduler/scheduler.module';
import { NotFoundException, forwardRef } from '@nestjs/common';
import { PrivateAPIServicesModule } from '../services/services.module';
import { PrivateAPIOfferingModule } from '../offering/offering.module';
import { UsageModule } from '../usage/usage.module';
import { SchedulerStatus, SupportedMeasurementFrequencies, schedulerType } from '../scheduler/dto/scheduler.dto';
import { paymentChannel } from './dto/create-customer.dto';

const BUSINESS_ID = 'myCoolCorp';
const SUBJECT = 'auth0|1234567890';
const OFFERING_ID = 'bc546e8a-3a2c-4089-8133-1efac1759ff5';
const CUSTOMER_ID = 'b9459f53-054b-4437-8ecd-b6f8070344fc';

describe('CustomerService', () => {
    let service: CustomerService;

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({
            providers: [CustomerService],
            imports: [
                InfluxModule,
                forwardRef(() => SchedulerModule),
                forwardRef(() => PrivateAPIServicesModule),
                forwardRef(() => PrivateAPIOfferingModule),
                forwardRef(() => UsageModule),
            ],
        }).compile();

        service = module.get<CustomerService>(CustomerService);
    });

    it('should be defined', () => {
        expect(service).toBeDefined();
    });

    describe('billing schedules', () => {
        let schedulerCreate: jest.SpyInstance;
        let schedulerRemove: jest.SpyInstance;

        const expectedSchedule = (customerId: string) => ({
            schedulerID: customerId,
            schedulerType: schedulerType.billing,
            schedulerStatus: SchedulerStatus.live,
            scheduleParameters: { customerId, businessID: BUSINESS_ID },
            rate: SupportedMeasurementFrequencies.monthly,
            subject: SUBJECT,
            businessID: BUSINESS_ID,
        });

        beforeEach(() => {
            jest.spyOn(service.InfluxService, 'loadPoints').mockResolvedValue(undefined);
            schedulerCreate = jest
                .spyOn(service.schedulerService, 'create')
                .mockResolvedValue({ message: 'Cron expression added', data: [] });
            schedulerRemove = jest
                .spyOn(service.schedulerService, 'remove')
                .mockResolvedValue({ message: 'Deleted Schedule', data: [] });
        });

        afterEach(() => {
            jest.restoreAllMocks();
        });

        it('creates a monthly billing schedule for a new customer with an offering', async () => {
            const { customerId } = await service.create(
                {
                    customerName: 'Wall Street Trading',
                    email: 'matt.sun@enterprise.tech',
                    paymentChannel: paymentChannel.Stripe,
                    offeringId: OFFERING_ID,
                    businessID: BUSINESS_ID,
                },
                SUBJECT
            );

            expect(schedulerCreate).toHaveBeenCalledWith(expectedSchedule(customerId));
        });

        it('does not create a billing schedule for a new customer without an offering', async () => {
            await service.create(
                {
                    customerName: 'Wall Street Trading',
                    email: 'matt.sun@enterprise.tech',
                    paymentChannel: paymentChannel.Stripe,
                    businessID: BUSINESS_ID,
                },
                SUBJECT
            );

            expect(schedulerCreate).not.toHaveBeenCalled();
        });

        describe('on update', () => {
            const mockExistingCustomer = (offeringId?: string) => {
                jest.spyOn(service, 'findOne').mockResolvedValue({
                    data: [
                        {
                            customerId: CUSTOMER_ID,
                            customerName: 'Wall Street Trading',
                            paymentChannel: paymentChannel.Stripe,
                            offeringId,
                        },
                    ],
                    message: 'Found Customer',
                } as never);
            };

            it('replaces the billing schedule when the customer gains an offering', async () => {
                mockExistingCustomer();

                await service.update(
                    { customerId: CUSTOMER_ID, businessID: BUSINESS_ID, offeringId: OFFERING_ID },
                    SUBJECT
                );

                expect(schedulerRemove).toHaveBeenCalledWith({
                    schedulerID: CUSTOMER_ID,
                    businessID: BUSINESS_ID,
                    isBillingQueue: true,
                });
                expect(schedulerCreate).toHaveBeenCalledWith(expectedSchedule(CUSTOMER_ID));
            });

            it('replaces the billing schedule when the customer changes offering', async () => {
                mockExistingCustomer('some-other-offering');

                await service.update(
                    { customerId: CUSTOMER_ID, businessID: BUSINESS_ID, offeringId: OFFERING_ID },
                    SUBJECT
                );

                expect(schedulerRemove).toHaveBeenCalledTimes(1);
                expect(schedulerCreate).toHaveBeenCalledWith(expectedSchedule(CUSTOMER_ID));
            });

            it('creates the billing schedule even when no previous schedule exists', async () => {
                mockExistingCustomer();
                schedulerRemove.mockRejectedValue(new NotFoundException('Schedule not found'));

                await expect(
                    service.update({ customerId: CUSTOMER_ID, businessID: BUSINESS_ID, offeringId: OFFERING_ID }, SUBJECT)
                ).resolves.toEqual({ message: 'Customer updated added', customerId: CUSTOMER_ID });
                expect(schedulerCreate).toHaveBeenCalledWith(expectedSchedule(CUSTOMER_ID));
            });

            it('leaves the billing schedule alone when the offering does not change', async () => {
                mockExistingCustomer(OFFERING_ID);

                await service.update(
                    { customerId: CUSTOMER_ID, businessID: BUSINESS_ID, customerName: 'New Name' },
                    SUBJECT
                );

                expect(schedulerRemove).not.toHaveBeenCalled();
                expect(schedulerCreate).not.toHaveBeenCalled();
            });
        });
    });
});

