            jest.spyOn(service.invoicesService, 'generateInvoiceForUsageTotal').mockRejectedValue(error);
            const loadPoints = jest.spyOn(service.InfluxService, 'loadPoints').mockResolvedValue(undefined);
            const publishEvent = jest.spyOn(AuditService, 'publishEvent').mockImplementation(() => undefined);

            await expect(service.create(buildJob())).resolves.toBeUndefined();

            expect(loadPoints).not.toHaveBeenCalled();
            expect(publishEvent).toHaveBeenCalledWith(
